import { R, X, lesson, mcq, numeric, short } from './helpers';
import type { Lesson } from '@/lib/types';

/**
 * SYSTEMS ENGINEERING.
 *
 * The SYSTEMS track: the discipline that makes a multi-part project finish.
 * Requirements, architecture and interfaces, verification, risk, trade studies,
 * integration and documentation - taught with the same numerical rigour as the
 * engineering tracks, because every one of these produces artefacts that can be
 * checked rather than opinions that can be argued about.
 *
 * Placed deliberately alongside the hardware tracks: these are the practices that
 * decide whether a robot with correct physics actually gets built, tested and
 * understood by anyone else.
 *
 * Order: requirements -> architecture and interfaces -> verification and
 * validation -> risk, FMEA and safety -> trade studies and decisions ->
 * integration and configuration management -> documentation and honest reporting.
 */
